pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 16 { insertion_sort(arr); return; }
    let depth = (n as f64).log2() as usize * 2;
    introsort(arr, depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], depth: usize) {
    let n = arr.len();
    if n <= 16 { insertion_sort(arr); return; }
    if depth == 0 { heapsort(arr); return; }
    let mid = arr.len() / 2;
    if arr[0] > arr[mid] { arr.swap(0, mid); }
    if arr[0] > arr[n - 1] { arr.swap(0, n - 1); }
    if arr[mid] > arr[n - 1] { arr.swap(mid, n - 1); }
    arr.swap(mid, n - 1);
    let pivot = arr[n - 1].clone();
    let mut i = 0;
    for j in 0..n - 1 {
        if arr[j] <= pivot { arr.swap(i, j); i += 1; }
    }
    arr.swap(i, n - 1);
    let (left, right) = arr.split_at_mut(i);
    introsort(left, depth - 1);
    if right.len() > 1 { introsort(&mut right[1..], depth - 1); }
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
    }
}

fn heapsort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    for i in (0..n / 2).rev() { sift_down(arr, i, n); }
    for i in (1..n).rev() { arr.swap(0, i); sift_down(arr, 0, i); }
}

fn sift_down<T: Ord>(arr: &mut [T], mut root: usize, end: usize) {
    while 2 * root + 1 < end {
        let mut child = 2 * root + 1;
        if child + 1 < end && arr[child] < arr[child + 1] { child += 1; }
        if arr[root] >= arr[child] { return; }
        arr.swap(root, child);
        root = child;
    }
}
